function agentWorkReferences(record,threadId) {
 const graphNodes=state?.nodes||[],edges=state?.edges||[],byId=new Map(graphNodes.map(n=>[n.id,n])),identities=new Set();
 if(record.id&&byId.has(record.id))identities.add(record.id);
 for(const n of graphNodes)if(n.kind==='Thread'&&threadId&&n.data.thread_id===threadId)identities.add(n.id);
 const taskIds=new Set(),explicit=record.task_id||record.data?.task_id;
 if(explicit)taskIds.add(explicit);
 for(const e of edges)if(e.relation==='executed_by'&&identities.has(e.target))taskIds.add(e.source);
 const tasks=[...taskIds].map(id=>byId.get(id)).filter(n=>n&&['Task','Subtask','PlanItem'].includes(n.kind)).sort((a,b)=>a.id.localeCompare(b.id));
 const unavailable=[...taskIds].filter(id=>!byId.has(id)||!['Task','Subtask','PlanItem'].includes(byId.get(id).kind));
 const producers=new Set([...identities,...tasks.map(n=>n.id)]),outputIds=new Set();
 for(const e of edges)if(producers.has(e.source)&&['produces','writes'].includes(e.relation))outputIds.add(e.target);
 const outputs=[...outputIds].map(id=>byId.get(id)).filter(n=>n&&['Artifact','File','Evidence'].includes(n.kind)).sort((a,b)=>String(b.updated_at||'').localeCompare(String(a.updated_at||''))||a.id.localeCompare(b.id));
 return {tasks:tasks.slice(0,3),outputs:outputs.slice(0,3),taskTotal:tasks.length,outputTotal:outputs.length,unavailable:unavailable.length,outputsUnavailable:[...outputIds].filter(id=>!byId.has(id)).length};
}
function renderAgentReferences(refs) {
 const link=n=>'<button class="textbutton" data-node="'+esc(n.id)+'">'+esc(n.title)+' · '+esc(n.id)+'</button>';
 const tasks=refs.tasks.map(n=>link(n)+' · '+esc(buckets[frontier.get(n.id)?.bucket]?.[0]||statuses[n.status]||n.status)).join('<br>');
 const outputs=refs.outputs.map(n=>{const source=n.data?.original_source||n.data?.source;return link(n)+(source?'<br><span class="muted">'+esc(String(source.uri||'').slice(0,240))+' · '+esc(String(source.locator||'').slice(0,160))+'</span>':'<br><span class="muted">未登记原件定位；可读对象关系，来源仍待核</span>');}).join('<br>');
 return (tasks||'当前载入范围内没有关联任务')+(refs.taskTotal>3?'<br>另 '+esc(refs.taskTotal-3)+' 项任务未显示':'')+(refs.unavailable?'<br>有 '+esc(refs.unavailable)+' 项任务定位未载入或类型不符':'')+'<br>关联产物（未自动验收）：<br>'+(outputs||'当前载入范围内没有关联产物')+(refs.outputTotal>3?'<br>另 '+esc(refs.outputTotal-3)+' 项产物未显示':'')+(refs.outputsUnavailable?'<br>有 '+esc(refs.outputsUnavailable)+' 项产物定位未载入':'');
}
function agentObservationRows() {
 const managed=(managedRuntime?.threads||[]).filter(t=>t.project_id===projectId),managedIds=new Set(managed.map(t=>t.thread_id));
 const rows=managed.map(t=>({name:t.model||'模型未知',target:t.thread_id+(t.turn_id?' / '+t.turn_id:''),references:agentWorkReferences(t,t.thread_id),status:managedRuntimeRead.state==='error'?'本次读取失败；旧日志快照，当前状态未知':!observationTime(t.at)?'无有效事件时间，当前状态未知':t.runtime_status==='disconnected'?'连接断开，轮次待核对':`事件记录：${runtimeStatusLabel(t.status)}（该时刻快照）`,observedAt:observationTime(t.at),recordedAt:null,readAt:observationTime(managedRuntimeRead.at),source:'工作区 App Server 事件日志',note:managedRuntimeRead.state==='error'?managedRuntimeRead.error:managedRuntimeRead.state==='loading'?'正在重新读取；显示上次日志快照':t.reason||''}));
 for(const n of state.nodes.filter(n=>['Agent','Thread','Run'].includes(n.kind))) {
  if(n.kind==='Thread'&&managedIds.has(n.data.thread_id))continue;
  const live=n.kind==='Thread'?observedThreads.get(n.data.thread_id):null;
  rows.push({name:n.kind==='Thread'?(n.data.agent||live?.title||n.title):n.kind==='Run'?(n.data.agent||'轮次'):n.title,target:n.kind==='Run'?(n.data.turn_id||n.id)+(n.data.thread_id?' / '+n.data.thread_id:''):n.data.thread_id||n.id,references:agentWorkReferences(n,n.data.thread_id),status:live?linkedObservationText(live):`历史登记：${n.data.runtime_status||n.data.status||n.status||'未知'}；当前状态未知`,observedAt:live?observationTime(live.observedAt):observationTime(n.data.observed_at),recordedAt:observationTime(n.updated_at),readAt:live?observationTime(live.checkedAt||live.observedAt):null,source:live?'Codex 独立只读连接':n.kind==='Run'?'项目图轮次登记':'项目图历史登记',note:live?.readError?'上次成功状态：'+observedThreadStatus(live.status):''});
 }
 rows.sort((a,b)=>String(b.observedAt||'').localeCompare(String(a.observedAt||'')));
 return rows;
}
function renderAgentStatus() {
 const box=$('agent-status');if(!box)return;const rows=agentObservationRows(),shown=rows.slice(0,50),coverage=typeof observedThreadsCoverage==='undefined'?null:observedThreadsCoverage;
 box.innerHTML=`<p>以下为观察记录，不保证当前在线。观察时间与记录更新时间分别显示。${coverage?.total?` 关联聊天只读观察本批 ${coverage.start+1}–${coverage.start+coverage.shown}/${coverage.total}，每批最多 5 条；其他项保留旧观察或未知。`:""}当前载入 ${rows.length} 条，显示 ${shown.length} 条${rows.length>50?'，已截断至 50 条':''}。${state.truncated?'项目图载入已截断；总数仅指当前载入范围。':''}${managedRuntime?.truncated?'受管日志查询已截断；尚有未载入聊天。':''}${managedRuntimeRead.state==='error'?'受管日志读取失败，保留旧快照；当前运行状态未知。':managedRuntimeRead.state==='loading'?'受管日志正在读取。':managedRuntimeRead.state==='unread'?'受管日志尚未读取。':''}</p>`+(shown.length?`<table class="list-table"><thead><tr><th>执行者</th><th>聊天与轮次</th><th>观察状态、时间与来源</th><th>任务与产物</th></tr></thead><tbody>${shown.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.target)}</td><td>${esc(r.status)}<br><span class="muted">${esc(r.source)} · 观察于 ${esc(observationTimeLabel(r.observedAt))}${r.recordedAt?'<br>记录更新于 '+esc(observationTimeLabel(r.recordedAt)):''}${r.readAt?'<br>读取于 '+esc(observationTimeLabel(r.readAt)):''}${r.note?'<br>'+esc(r.note):''}</span></td><td>${renderAgentReferences(r.references)}</td></tr>`).join('')}</tbody></table>`:'<p>当前载入范围没有执行者观察记录。</p>');
}
async function loadManagedRuntime() {const ticket=epoch,box=$('managed-runtime');if(!box)return;managedRuntimeRead={state:'loading',at:managedRuntimeRead.at,error:''};renderAgentStatus();try{const d=await request(scoped('/api/runtime'));if(ticket!==epoch||!$('managed-runtime'))return;managedRuntime=d;managedRuntimeRead={state:'ok',at:Date.now(),error:''};renderAgentStatus();const taskName=id=>nodes.get(id)?.title||id;box.innerHTML=`<p>${esc(d.scope)}。聊天轮次结束不会自动完成任务。</p>${d.threads.length?d.threads.map(t=>`<div class="quick-row"><div><strong>${esc(taskName(t.task_id))}</strong><br><span class="muted">${esc(t.thread_id)} · ${esc(runtimeStatusLabel(t.status))}${t.reason?' · '+esc(t.reason):''}</span>${renderManagedOutput(t)}</div><div>${['idle','completed','failed','interrupted'].includes(t.status)?`<button class="secondary" data-managed="continue" data-thread-id="${esc(t.thread_id)}">继续</button>`:''}${t.status==='inProgress'?`<button class="secondary" data-managed="steer" data-thread-id="${esc(t.thread_id)}">补充</button>`:''}${['inProgress','waitingApproval','waitingInput'].includes(t.status)?`<button class="secondary" data-managed="interrupt" data-thread-id="${esc(t.thread_id)}">中断</button>`:''}${t.status==='unknown'?`<button class="secondary" data-managed="reconcile" data-thread-id="${esc(t.thread_id)}">核对原轮次</button>`:''}</div></div>`).join(''):'<p>当前项目尚无由工作区管理的聊天。</p>'}${d.pending_approvals.map(a=>`<div class="quick-row"><div><strong>待处理审批</strong><br><span class="muted">请求类型：${esc(a.method)}</span><br>${esc(a.params.command||a.params.reason||a.params.itemId||'请核对准确请求')}<br><span class="muted">${esc(a.thread_id)} · ${esc(a.turn_id)} · 请求 ${esc(a.request_id)}</span></div><button class="primary" data-managed="approval" data-thread-id="${esc(a.thread_id)}" data-approval-id="${esc(a.request_id)}">处理审批</button></div>`).join('')}${renderPendingInputs(d)}`;}catch(e){if(ticket===epoch&&$('managed-runtime')){managedRuntimeRead={state:'error',at:Date.now(),error:e.message};$('managed-runtime').textContent=e.message;renderAgentStatus();}}}
async function managedAction(action,args={}) {if(formProject&&formProject!==projectId)throw new Error('项目已切换，请重新打开表单');const d=await request('/api/runtime',{method:'POST',headers:{'Content-Type':'application/json','X-PGW-CSRF':session.csrf},body:JSON.stringify({project_id:projectId,action,request_id:formRequestId||crypto.randomUUID(),...args})});await loadManagedRuntime();if(d.result?.rejected)throw new Error(d.result.error||'运行请求已被拒绝，请刷新并核对原轮次');return d.result;}
function renderManagedOutput(t){const o=t.output;if(!o)return '';return `<details${['inProgress','waitingApproval','waitingInput'].includes(t.status)?' open':''}><summary>最近输出${o.truncated?'（尾部摘录，已截断）':''}</summary><p class="muted">轮次 ${esc(o.turn_id)} · 输出项 ${esc(o.item_id)} · 观察于 ${esc(o.observed_at)} · 最多 ${esc(o.limit_chars)} 字符。${o.complete?'输出项结束':'输出仍可能不完整'}；运行与任务状态分别核对，完整历史请读真实聊天原文。</p><pre>${esc(o.text)}</pre></details>`;}
function renderPendingInputs(d){return (d.pending_inputs||[]).map(a=>`<div class="quick-row"><div><strong>${a.params.isBlocking?'等待用户输入':'用户问题（不阻塞）'}</strong><br>${(a.params.questions||[]).map(q=>esc(q.question)).join('<br>')}<br><span class="muted">${esc(a.thread_id)} · ${esc(a.turn_id)} · 请求 ${esc(a.request_id)}</span>${a.params.questions.some(q=>q.isSecret)?'<br>敏感输入须由用户在宿主处理；工作区不代答':''}</div>${a.params.questions.some(q=>q.isSecret)?'':`<button class="primary" data-managed="input" data-thread-id="${esc(a.thread_id)}" data-input-id="${esc(a.request_id)}">提交回答</button>`}</div>`).join('');}
function managedInputForm(t,element){const a=(managedRuntime.pending_inputs||[]).find(a=>a.thread_id===t.thread_id&&a.request_id===element.dataset.inputId&&a.turn_id===t.turn_id);if(!a)throw new Error('待输入问题已变化，请刷新');if(a.params.questions.some(q=>q.isSecret))throw new Error('敏感输入请由用户在宿主处理');return openForm('回答本次问题',`<p class="panel-note">聊天 ${esc(a.thread_id)} · 轮次 ${esc(a.turn_id)} · 请求 ${esc(a.request_id)}。请逐题作决定；没有默认回答，关闭表单不发送，也不会代答审批。</p>`+a.params.questions.map((q,i)=>`<p>${esc(q.question)}</p>${(q.options||[]).map(o=>`<p class="muted">${esc(o.label)}：${esc(o.description)}</p>`).join('')}`+field('answer_'+i,q.header||q.id,q.options?.length&&!q.isOther?'select':'textarea','',q.options?.length&&!q.isOther?[['','请选择，不默认作答'],...q.options.map(o=>[o.label,o.label])]:[])).join(''),async values=>{const answers={};a.params.questions.forEach((q,i)=>{const value=values['answer_'+i];if(!value?.trim())throw new Error('请明确回答每一道问题');answers[q.id]={answers:[value]};});const r=await managedAction('input',{thread_id:a.thread_id,turn_id:a.turn_id,input_request_id:a.request_id,answers});return r.uncertain?'回答状态待核对，请勿重发':'本次问题回答已提交';});}
async function previewManagedCreateContext(){const task=$('edit-form').elements.namedItem('task_id').value,ticket=epoch,project=projectId,requestId=formRequestId;const c=await request(scoped('/api/runtime/context')+'&task='+encodeURIComponent(task));if(ticket!==epoch||project!==projectId||requestId!==formRequestId||$('edit-form').elements.namedItem('task_id').value!==task)return;if(!c.eligible)throw new Error('任务不可执行：'+c.reasons.join('；'));managedCreatePreview=c;$('managed-context-preview').innerHTML=renderExecutionContext(c);}
async function managedExecutionForm(action,t,base){const ticket=epoch,project=projectId;const c=await request(scoped('/api/runtime/context')+'&task='+encodeURIComponent(t.task_id));if(ticket!==epoch||project!==projectId)throw new Error('项目已切换，请重新预览');if(!c.eligible)throw new Error('任务不可执行：'+c.reasons.join('；'));const summary=renderExecutionContext(c);return openForm(action==='continue'?'继续工作区聊天':'向当前轮次补充',summary+field('text','发送给聊天的文字','textarea')+(action==='continue'?field('interaction_mode','本轮交互模式','select','default',[['default','正常执行'],['plan','仅规划（允许用户问题）']]):''),async a=>{const r=await managedAction(action,{...base,...a,context_fingerprint:c.fingerprint});return r.uncertain?'请求状态待核对，请勿重发':`已发送至 ${r.turn_id||t.turn_id}`;});}
function renderExecutionContext(c){return `<p class="panel-note">项目 ${esc(c.project_id)} · 目录 ${esc(c.root)}<br>任务 ${esc(c.task.id)} · 版本 ${esc(c.task.version)} · 上下文 ${esc(c.bytes)}/${esc(c.limit_bytes)} 字节<br>${esc(c.boundary)}</p><details><summary>查看将发送的任务上下文</summary><pre>${esc(JSON.stringify({task:c.task,dependencies:c.dependencies,human_gates:c.human_gates,source_refs:c.source_refs},null,2))}</pre><p>可选关系省略 ${esc(c.omitted_optional_refs)} 项；原件定位不等于已读。指纹 ${esc(c.fingerprint)}</p></details>`;}
function managedForm(action,element) {const t=managedRuntime?.threads.find(x=>x.thread_id===element?.dataset.threadId);if(action==='create'){const options=state.frontier.filter(f=>['Ready','In Progress'].includes(f.bucket)).map(f=>nodes.get(f.id)).filter(n=>n&&['Task','Subtask','PlanItem'].includes(n.kind)).map(n=>[n.id,n.title]);if(!options.length)throw new Error('当前项目没有通过前置与人工门禁的可执行任务');managedCreatePreview=null;return openForm('新建受管聊天',`<p class="panel-note">只管理此入口新建的 App Server 聊天；先核对任务和项目目录。新建不会自动启动回合。</p>`+field('task_id','可执行任务','select',options[0][0],options)+field('model','模型','select','gpt-6-luna',[['gpt-5.6-terra','Terra（须明确选择；旧隔离验证范围）'],['gpt-6-luna','Luna（默认路由；可用性以实际请求为准）']])+`<button type="button" class="secondary" data-action="managed-context-preview">预览所选任务上下文</button><div id="managed-context-preview"></div>`,async a=>{if(!managedCreatePreview||managedCreatePreview.task.id!==a.task_id)throw new Error('请先预览所选任务上下文；未创建');const r=await managedAction('create',{...a,context_fingerprint:managedCreatePreview.fingerprint});return r.linked?'聊天已创建并关联；可从本页继续。':`聊天已创建，项目关联失败：${r.link_error||'未知'}`;});}if(!t)throw new Error('聊天不属于当前项目的工作区管理范围');const base={task_id:t.task_id,thread_id:t.thread_id,turn_id:t.turn_id};if(action==='continue'||action==='steer')return managedExecutionForm(action,t,base);if(action==='interrupt'||action==='reconcile')return openForm(action==='interrupt'?'中断当前轮次':'核对原轮次',`<p class="panel-note">${esc(t.thread_id)} · ${esc(t.turn_id||'无已知轮次')}。${action==='interrupt'?'中断只发给准确的轮次；未确认时不重发。':'只读核对原轮次，不创建新回合。'}</p>`,async()=>{const r=await managedAction(action,base);return r.uncertain?'操作状态待核对，请勿重发':`当前状态：${r.status||'已提交'}`;});if(action==='input')return managedInputForm(t,element);if(action==='approval'){const a=managedRuntime.pending_approvals.find(x=>x.request_id===element.dataset.approvalId&&x.thread_id===t.thread_id);if(!a)throw new Error('审批请求已变化，请刷新');const offered=a.params.availableDecisions;const choices=[['decline','拒绝'],['accept','同意这一次'],['cancel','取消本次执行']].filter(([value])=>!offered||offered.includes(value));if(!choices.length)throw new Error('该审批没有支持的单次决定，请在宿主核对');return openForm('处理本次审批',`<p class="panel-note">${esc(a.method)}<br>${esc(a.params.command||a.params.reason||a.params.itemId||'无命令说明')}<br>聊天 ${esc(a.thread_id)} · 轮次 ${esc(a.turn_id)} · 请求 ${esc(a.request_id)}</p>`+field('decision','您的决定','select',choices.find(([value])=>value==='cancel')?.[0]||choices[0][0],choices),async v=>{const r=await managedAction('approval',{...base,turn_id:a.turn_id,approval_request_id:a.request_id,...v});return r.uncertain?'审批发送状态待核对，请勿重发':'已发送决定：'+r.decision;});}}
async function observeLinkedThreads() {
 if(observingThreads||Date.now()-observedThreadsAt<60000)return;
 const ticket=epoch, all=[...new Map(state.nodes.filter(n=>n.kind==='Thread'&&n.data.thread_id).map(n=>[n.data.thread_id,n])).values()],start=observedThreadsOffset<all.length?observedThreadsOffset:0,linked=all.slice(start,start+5);
 observingThreads=true;observedThreadsAt=Date.now();
 try {
  const results=[];
  for(const n of linked) {
   if(ticket!==epoch)break;
   try {const d=await request(scoped('/api/thread-observation?'+new URLSearchParams({id:n.id,expected_version:String(n.version)})));results.push([n.data.thread_id,{title:d.thread.title,status:d.thread.status,observedAt:d.observed_at,checkedAt:Date.now(),readError:null}]);}
   catch(e) {results.push([n.data.thread_id,{...(observedThreads.get(n.data.thread_id)||{}),checkedAt:Date.now(),readError:e.message||'读取失败'}]);}
  }
  if(ticket!==epoch)return;
  observedThreadsCoverage={total:all.length,start,shown:linked.length,truncated:all.length>linked.length};
  observedThreadsOffset=start+linked.length>=all.length?0:start+linked.length;
  observedThreads=new Map([...observedThreads,...results]);
  if(view==='threads'&&!kindFilter)renderThreads();
  if(nodes.get(selected)?.kind==='Thread')renderInspector();
 } finally {observingThreads=false;}
}
async function loadDiscoveredThreads(more=false) { const ticket=epoch; const box=$('discovered-threads'); if(!box)return; try { if(!more)threadCursor=null; const params=new URLSearchParams({search:threadSearch,limit:'30'});if(more&&threadCursor)params.set('cursor',threadCursor);const d=await request(scoped('/api/discover-threads?'+params));if(ticket!==epoch||view!=='threads'||!$('discovered-threads'))return;threadCursor=d.next_cursor;const known=new Set(state.nodes.filter(n=>n.kind==='Thread').map(n=>n.data.thread_id));const html=d.threads.map(t=>`<div class="quick-row"><button class="textbutton" data-thread="${esc(t.id)}">${esc(t.title)}</button><span class="muted">${esc(t.cwd)} · ${esc(t.model||'模型未知')} · ${known.has(t.id)?'已登记':'未登记'}</span></div>`).join('')||'<p class="muted">当前范围无匹配聊天。</p>';if(more)box.querySelector('[data-action="more-threads"]')?.remove();if(more)box.insertAdjacentHTML('beforeend',html+(threadCursor?'<button class="secondary" data-action="more-threads">更多聊天</button>':''));else box.innerHTML=html+(threadCursor?'<button class="secondary" data-action="more-threads">更多聊天</button>':'');}catch(e){if(ticket===epoch&&box)box.textContent=e.message;} }
