async function loadSourceInventory(more=false) {
 const ticket=epoch, target=formProject, box=$('source-inventory');if(!box)return;
 const offset=more?sourceInventoryOffset:0;if(more&&offset==null)return;
 try {
  const d=await request(scoped('/api/source-inventory?'+new URLSearchParams({offset,limit:40})));
  if(ticket!==epoch||target!==projectId||!$('source-inventory'))return;
  sourceInventoryOffset=d.next_offset;
  const names={matched:'当前哈希与单一登记版本一致',changed:'当前文件与登记版本不同',multiple_recorded_versions:'图中有多个登记版本，需逐项比较',unregistered_hash:'未登记原始哈希',large_unchecked:'大文件未核当前内容',outside_project_unchecked:'项目目录外，未核当前内容',missing:'路径当前不可用'};
  const rows=d.files.map(f=>`<tr><td class="path">${esc(f.uri)}</td><td>${esc(names[f.status]||f.status)}<br>${f.size==null?'':esc(f.size+' 字节')}</td><td>${f.reference_count} 个图引用${f.references.length?'<br>'+esc(f.references.map(x=>x.id).join('、')):''}</td><td class="path">${esc(f.current_sha256||'未计算')}<br>登记：${esc(f.recorded_sha256.join('、')||'无')}</td></tr>`).join('');
  if(!more)box.innerHTML=`<p>${esc(d.scope)}。共有 ${d.total} 个路径${d.graph_truncated?'；图对象检索已截断':''}；当前显示 ${d.offset+1}–${d.offset+d.files.length}。</p><div style="max-height:25vh;overflow:auto"><table class="list-table"><thead><tr><th>文件路径</th><th>当前核对状态</th><th>图中引用</th><th>当前 / 登记 SHA-256</th></tr></thead><tbody id="source-inventory-rows">${rows}</tbody></table></div><button type="button" class="secondary" data-action="more-sources" ${sourceInventoryOffset==null?'hidden':''}>更多文件来源</button>`;
  else { $('source-inventory-rows').insertAdjacentHTML('beforeend',rows);box.querySelector('[data-action="more-sources"]').hidden=sourceInventoryOffset==null;box.querySelector('p').textContent=`${d.scope}。共有 ${d.total} 个路径；已显示至 ${d.offset+d.files.length}。`; }
 } catch(e) { if(ticket===epoch&&box)box.textContent=e.message; }
}

